outputs.yaml:
# SECS 2 calibration -> CamillaDSP v4 (generated)
# inputs 2: L, LFE / outputs 2: L, SW1
# LFE: gain +10 dB, LR24 lowpass 1e-05 Hz -> every sub bus (same sub gain/polarity/filters/delay as the bass-managed mains), no MIMO
# sub SW1: fixed gain -0.000 dB, delay 0.000 ms, polarity inverted, allpass 2.7 Hz Q 1.235, fixed HP 1e-05 Hz BW12, fixed LP 1e+16 Hz LR48, fixed PEQ 10.0 Hz Q 1.000 -1.23 dB
#
# ---- HOW TO USE (CamillaDSP 4.1.x + CamillaGUI 4.1) ----
# 1) Files: this file goes to camilladsp/configs, the wav files to camilladsp/coeffs
#    (same layout as this export). CamillaGUI: Files tab, upload the wav files under Filters FIRST,
#    then this file under Configs. FIR paths are relative to this file (../coeffs/...).
# 2) Devices: capture/playback below are FILE placeholders (in.raw / out.raw) - change them:
#    capture = loopback (Windows: Wasapi "CABLE Output (VB-Audio Virtual Cable)", Mac: CoreAudio
#    "BlackHole 16ch"), playback = your audio interface. format: empty or F32 (F32_LE is for files only).
#    samplerate 48000 (Windows: set both devices' default format to 48000 Hz too).
#    Different clocks (loopback -> interface): enable_rate_adjust; Windows also resampler AsyncSinc.
#    Capture channels = route_in "in", playback channels = route_out "out".
# 3) Channel numbers start at 0 (interface output 1 = 0). Default routing is 1:1:
#    ch  input (capture -> route_in)   output (route_out -> playback)
#     0  L                               L
#     1  LFE                             SW1
#    To move a channel change only the Mixers route_in (source "channel") or route_out ("dest").
#    More interface outputs: raise route_out "out" and the playback channels to the same number.
#    Players send LFE 4th (Windows 7.1: FL FR FC LFE BL BR SL SR) - reorder them in route_in.
title: "SECS 2"
description: "inputs 0 L, 1 LFE | outputs 0 L, 1 SW1 | numbers start at 0, change routing in Mixers route_in / route_out | devices are file placeholders: set capture = loopback, playback = interface"
devices:
  samplerate: 48000
  chunksize: 1024
  capture: {"type": "RawFile", "channels": 1}
  playback: {"type": "File", "channels": 2}
filters:
  in_L_peq0: {"type": "Biquad", "parameters": {"type": "Peaking", "freq": 1.2345, "q": 0.12345, "gain": -0.0001}}
  lfe_gain: {"type": "Gain", "parameters": {"gain": 10.0, "inverted": false}}
  lfe_lp: {"type": "BiquadCombo", "parameters": {"type": "LinkwitzRileyLowpass", "freq": 1e-05, "order": 4}}
  main_L_gain: {"type": "Gain", "parameters": {"gain": -0.0, "inverted": false}}
  main_L_xopeq0: {"type": "Biquad", "parameters": {"type": "Peaking", "freq": 1e+16, "q": 2.675, "gain": -2.675}}
  main_L_hp: {"type": "BiquadCombo", "parameters": {"type": "LinkwitzRileyHighpass", "freq": 80.0, "order": 4}}
  send_L_lp: {"type": "BiquadCombo", "parameters": {"type": "LinkwitzRileyLowpass", "freq": 80.0, "order": 4}}
  main_L_delay: {"type": "Delay", "parameters": {"delay": 0, "unit": "samples", "subsample": false}}
  sub_SW1_peq0: {"type": "Biquad", "parameters": {"type": "Peaking", "freq": 80.0, "q": 0.70715, "gain": -0.0001}}
  sub_SW1_fixed_hp: {"type": "BiquadCombo", "parameters": {"type": "ButterworthHighpass", "freq": 1e-05, "order": 2}}
  sub_SW1_fixed_lp: {"type": "BiquadCombo", "parameters": {"type": "LinkwitzRileyLowpass", "freq": 1e+16, "order": 8}}
  sub_SW1_fixed_peq0: {"type": "Biquad", "parameters": {"type": "Peaking", "freq": 10.0, "q": 1.00005, "gain": -1.2345}}
  sub_SW1_ap0: {"type": "Biquad", "parameters": {"type": "Allpass", "freq": 2.675, "q": 1.23455}}
  sub_SW1_delay: {"type": "Delay", "parameters": {"delay": 0, "unit": "samples", "subsample": false}}
mixers:
  route_in: {"description": "capture channel -> SECS input (edit source channel to move an input)", "channels": {"in": 2, "out": 2}, "mapping": [{"dest": 0, "sources": [{"channel": 0, "gain": 0, "inverted": false}]}, {"dest": 1, "sources": [{"channel": 1, "gain": 0, "inverted": false}]}]}
  route_out: {"description": "SECS output -> playback channel (edit dest to move an output)", "channels": {"in": 2, "out": 2}, "mapping": [{"dest": 0, "sources": [{"channel": 0, "gain": 0, "inverted": false}]}, {"dest": 1, "sources": [{"channel": 1, "gain": 0, "inverted": false}]}]}
  split: {"channels": {"in": 2, "out": 4}, "mapping": [{"dest": 0, "sources": [{"channel": 0, "gain": 0, "inverted": false}]}, {"dest": 1, "sources": [{"channel": 1, "gain": 0, "inverted": false}]}, {"dest": 2, "sources": [{"channel": 0, "gain": 0, "inverted": false}]}, {"dest": 3, "sources": [{"channel": 1, "gain": 0, "inverted": false}]}]}
  bus: {"channels": {"in": 4, "out": 2}, "mapping": [{"dest": 0, "sources": [{"channel": 0, "gain": 0, "inverted": false}]}, {"dest": 1, "sources": [{"channel": 2, "gain": -0.0, "inverted": true}, {"channel": 3, "gain": -0.0, "inverted": true}]}]}
pipeline:
  - {"type": "Mixer", "name": "route_in"}
  - {"type": "Filter", "channels": [0], "names": ["in_L_peq0"]}
  - {"type": "Filter", "channels": [1], "names": ["lfe_gain", "lfe_lp"]}
  - {"type": "Mixer", "name": "split"}
  - {"type": "Filter", "channels": [2], "names": ["send_L_lp"]}
  - {"type": "Filter", "channels": [0], "names": ["main_L_gain", "main_L_xopeq0", "main_L_hp", "main_L_delay"]}
  - {"type": "Mixer", "name": "bus"}
  - {"type": "Filter", "channels": [1], "names": ["sub_SW1_peq0", "sub_SW1_fixed_hp", "sub_SW1_fixed_lp", "sub_SW1_fixed_peq0", "sub_SW1_ap0", "sub_SW1_delay"]}
  - {"type": "Mixer", "name": "route_out"}
